import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.iWwp2X7T.js";const _=JSON.parse('{"title":"事件证据","description":"Mobile Inspector development documentation · 事件证据","frontmatter":{"title":"事件证据","description":"Mobile Inspector development documentation · 事件证据"},"headers":[],"relativePath":"zh/reference/incidents.md","filePath":"zh/reference/incidents.md"}'),r={name:"zh/reference/incidents.md"};function i(c,e,s,d,p,l){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="事件证据" tabindex="-1">事件证据 <a class="header-anchor" href="#事件证据" aria-label="Permalink to &quot;事件证据&quot;">​</a></h1><p>规则识别候选观察，不直接确认客户端缺陷。HTTP 失败、配置的业务拒绝、预期取消和证据缺失分别处理。</p><h2 id="证据窗口" tabindex="-1">证据窗口 <a class="header-anchor" href="#证据窗口" aria-label="Permalink to &quot;证据窗口&quot;">​</a></h2><p>单个事件最多保存前 30 秒的 120 个引用和后 10 秒的 80 个引用，总计最多 200。以宿主收到时间为准，设备时钟不能延长窗口。同指纹只在原期限内合并；窗口关闭只触发一次就绪，即使后续没有新事件。</p><p>每项目最多 100 个事件、实例最多 400 个。清除、撤销、到期与代次变化会移除派生记录并失效回调，不写磁盘事件快照。</p><h2 id="完整性与含义" tabindex="-1">完整性与含义 <a class="header-anchor" href="#完整性与含义" aria-label="Permalink to &quot;完整性与含义&quot;">​</a></h2><p>延迟依据 response 或 complete 中有限 duration/elapsed，首字节时间不代表总延迟。无 code 错误仅产生通用网络失败，不从自由文本猜因；未知 code 不分类。取消属于信息，不作为自动缺陷证据。</p><p>缺口包括窗口截断、序号缺失、采集上限、证据不可用与事件上限。已知构建映射只是来源信息，不能证明源码内容或行号；缺失和歧义保持显式。</p><p>列表与详情绑定项目代次，默认 50 条、最多 200 条且字节有界。默认摘要，正文每次读取都需当前许可。翻页见 <a href="./mcp">MCP</a>，编排见<a href="./diagnosis">诊断生命周期</a>。</p>',9)])])}const m=a(r,[["render",i]]);export{_ as __pageData,m as default};
